from pathlib import Path
import re

p=Path('pc-relay/roon_netshare_relay_v3.py')
s=p.read_text(encoding='utf-8')

s=s.replace('# FINAL v2.4: native RAAT discovery + stable proxy across HiBy RAAT port rotations.',
            '# FINAL v2.5: stable RAAT proxy + stale-backend invalidation + fast recovery.')
s=s.replace('VERSION="2.4-FINAL-STABLE-RAAT-PROXY"','VERSION="2.5-FINAL-FAST-BACKEND-RECOVERY"')

old='''PROBE_INTERVAL=4.0\nANNOUNCE_REFRESH=12.0\n'''
new='''PROBE_INTERVAL=4.0\nANNOUNCE_REFRESH=12.0\nRECOVERY_PROBE_INTERVAL=0.30\nRECOVERY_HOLD=10.0\nSTALE_SAME_PORT_BLOCK=8.0\nSESSION_RECOVERY_TIMEOUT=30.0\n'''
if old not in s: raise SystemExit('constants target not found')
s=s.replace(old,new,1)

old='''announce_lock=threading.Lock()\nannounce_state={}\n'''
new='''announce_lock=threading.Lock()\nannounce_state={}\nrecovery_lock=threading.Lock()\nrecovery_until=0.0\n'''
if old not in s: raise SystemExit('state target not found')
s=s.replace(old,new,1)

pat=re.compile(r'def ensure_stable_forwarder\(unique_id,prop,target_ip,target_port\):.*?\ndef detach_sid_without_closing',re.S)
block='''def request_recovery(seconds=RECOVERY_HOLD):\n    global recovery_until\n    with recovery_lock:\n        recovery_until=max(recovery_until,time.time()+float(seconds))\n    probe_now.set()\n\n\ndef recovery_active():\n    with recovery_lock:\n        return time.time()<recovery_until\n\n\ndef ensure_stable_forwarder(unique_id,prop,target_ip,target_port):\n    key=stable_key(unique_id,prop)\n    changed=False\n    now=time.time();new_target=(target_ip,int(target_port))\n    with stable_changed:\n        e=stable_forwards.get(key)\n        if e is None:\n            ss=socket.socket(socket.AF_INET,socket.SOCK_STREAM)\n            ss.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)\n            ss.bind(("0.0.0.0",0));ss.listen(32)\n            port=ss.getsockname()[1]\n            e={"key":key,"unique_id":unique_id,"prop":prop,"port":port,"ss":ss,\n               "target_ip":target_ip,"target_port":int(target_port),"generation":1,\n               "updated":now,"valid":True,"blocked_target":None,"blocked_until":0.0}\n            stable_forwards[key]=e\n            threading.Thread(target=stable_accept,args=(key,),daemon=True).start()\n            base.log("STABLE RAAT PROXY CREATE · proxy="+str(port)+" -> R8 "+target_ip+":"+str(target_port)+" · key="+key)\n            changed=True\n        else:\n            old_target=(e["target_ip"],e["target_port"])\n            if old_target!=new_target:\n                e["target_ip"],e["target_port"]=new_target\n                e["generation"]+=1;e["updated"]=now;e["valid"]=True\n                e["blocked_target"]=None;e["blocked_until"]=0.0;changed=True\n                base.log("RAAT TARGET ROTATED · proxy="+str(e["port"])+" · "+old_target[0]+":"+str(old_target[1])+" -> "+new_target[0]+":"+str(new_target[1]))\n                stable_changed.notify_all()\n            elif not e.get("valid",True):\n                blocked=e.get("blocked_target")\n                # A tunnel reconnect may legitimately keep the same HiBy port: the first fresh\n                # response from the new tunnel revalidates it immediately. An OPEN_ERR, however,\n                # quarantines that exact target so we never hammer a known-dead port repeatedly.\n                if blocked is None or blocked!=new_target or now>=float(e.get("blocked_until",0.0)):\n                    e["valid"]=True;e["generation"]+=1;e["updated"]=now\n                    e["blocked_target"]=None;e["blocked_until"]=0.0;changed=True\n                    base.log("RAAT TARGET REVALIDATED · proxy="+str(e["port"])+" -> R8 "+new_target[0]+":"+str(new_target[1]))\n                    stable_changed.notify_all()\n        return e["port"],changed\n\n\ndef get_target(key):\n    with stable_lock:\n        e=stable_forwards.get(key)\n        if not e or not e.get("valid",True):return None\n        return e["target_ip"],e["target_port"],e["generation"],e["port"]\n\n\ndef invalidate_entry(key,reason,failed_target=True):\n    changed=False\n    with stable_changed:\n        e=stable_forwards.get(key)\n        if not e:return False\n        current=(e["target_ip"],e["target_port"])\n        already_invalid=not e.get("valid",True)\n        if failed_target and already_invalid and e.get("blocked_target")==current:\n            request_recovery();return False\n        e["valid"]=False;e["generation"]+=1;e["updated"]=time.time()\n        if failed_target:\n            e["blocked_target"]=current\n            e["blocked_until"]=time.time()+STALE_SAME_PORT_BLOCK\n        else:\n            e["blocked_target"]=None;e["blocked_until"]=0.0\n        stable_changed.notify_all();changed=True\n        base.log("RAAT BACKEND INVALIDATED · proxy="+str(e["port"])+" · target="+current[0]+":"+str(current[1])+" · "+str(reason))\n    request_recovery()\n    return changed\n\n\ndef invalidate_all(reason):\n    did=False\n    with stable_changed:\n        for e in stable_forwards.values():\n            if e.get("valid",True) or e.get("blocked_target") is not None:\n                e["valid"]=False;e["generation"]+=1;e["updated"]=time.time()\n                # Tunnel replacement is not proof the HiBy port died. A fresh response on the\n                # new tunnel may revalidate the same port immediately.\n                e["blocked_target"]=None;e["blocked_until"]=0.0;did=True\n        if did:stable_changed.notify_all()\n    if did:\n        base.log("RAAT BACKENDS INVALIDATED · "+str(reason))\n        request_recovery()\n    return did\n\n\ndef wait_valid_target(key,timeout):\n    end=time.time()+timeout\n    with stable_changed:\n        while True:\n            e=stable_forwards.get(key)\n            if e and e.get("valid",True):\n                return e["target_ip"],e["target_port"],e["generation"],e["port"]\n            left=end-time.time()\n            if left<=0:return None\n            stable_changed.wait(min(left,0.5))\n\n\ndef detach_sid_without_closing'''
s,n=pat.subn(block,s,count=1)
if n!=1: raise SystemExit('stable state block target not found')

pat=re.compile(r'def stable_open_once\(local,addr,key,attempt\):.*?\ndef stable_accept',re.S)
block='''def stable_open_once(local,addr,key,attempt):\n    target=get_target(key)\n    if not target:return False,"backend invalid / waiting fresh RAAT target",0,None\n    target_ip,target_port,generation,proxy_port=target\n    t=base.get_tunnel()\n    if not t or not t.alive:return False,"R8 tunnel unavailable",generation,target\n    sid=base.alloc_even_stream();ev=threading.Event()\n    with base.streams_lock:base.streams[sid]=local\n    with base.open_lock:\n        base.open_events[sid]=ev;base.open_errors.pop(sid,None)\n    try:\n        t.send(base.OPEN_PC,sid,base.endpoint_packet(target_ip,target_port))\n        base.log("PC Roon TCP pending · "+str(addr)+" -> stableProxy:"+str(proxy_port)+" -> R8 "+target_ip+":"+str(target_port)+" · stream="+str(sid)+" · try="+str(attempt))\n        if not ev.wait(6.0):\n            detach_sid_without_closing(sid,local)\n            return False,"R8 OPEN_OK timeout",generation,target\n        with base.open_lock:err=base.open_errors.get(sid)\n        if err:\n            detach_sid_without_closing(sid,local)\n            return False,err,generation,target\n        if t is not base.get_tunnel():\n            detach_sid_without_closing(sid,local)\n            return False,"tunnel changed",generation,target\n        base.log("R8 OUTPUT REAL · PC Roon "+str(addr)+" -> stableProxy:"+str(proxy_port)+" -> R8 "+target_ip+":"+str(target_port)+" · stream="+str(sid))\n        base.pump_socket(t,sid,local)\n        return True,None,generation,target\n    except Exception as e:\n        detach_sid_without_closing(sid,local)\n        return False,str(e),generation,target\n\n\ndef stable_session(local,addr,key):\n    try:\n        local.setsockopt(socket.IPPROTO_TCP,socket.TCP_NODELAY,1)\n        local.setsockopt(socket.SOL_SOCKET,socket.SO_KEEPALIVE,1)\n        deadline=time.time()+SESSION_RECOVERY_TIMEOUT\n        attempt=0\n        while time.time()<deadline:\n            target=get_target(key)\n            if target is None:\n                request_recovery()\n                wait_valid_target(key,min(1.0,max(0.05,deadline-time.time())))\n                continue\n            attempt+=1\n            ok,err,generation,target=stable_open_once(local,addr,key,attempt)\n            if ok:return\n            if err in ("R8 tunnel unavailable","tunnel changed"):\n                invalidate_all("R8 tunnel unavailable during RAAT open")\n            else:\n                # Critical v2.5 rule: one OPEN failure makes this exact backend stale.\n                # Never retry the same dead target just because a timer expired.\n                invalidate_entry(key,"OPEN failed: "+str(err),True)\n            base.log("RAAT FAST RECOVERY · keep PC Roon socket open · stale target blocked · "+str(err))\n            request_recovery()\n            wait_valid_target(key,min(2.0,max(0.05,deadline-time.time())))\n        base.log("R8 OUTPUT TCP 최종 실패 · PC Roon "+str(addr)+" · recovery timeout · stable key="+key)\n    finally:\n        try:local.shutdown(socket.SHUT_RDWR)\n        except:pass\n        try:local.close()\n        except:pass\n\n\ndef stable_accept'''
s,n=pat.subn(block,s,count=1)
if n!=1: raise SystemExit('stable session block target not found')

pat=re.compile(r'def probe_loop\(\):.*?\ndef main\(\):',re.S)
block='''def probe_loop():\n    last_tunnel=None\n    while True:\n        t=base.get_tunnel()\n        if t and t.alive:\n            try:\n                if t is not last_tunnel:\n                    if last_tunnel is not None or stable_forwards:\n                        invalidate_all("R8 tunnel connected/replaced · fresh backend required")\n                    base.log("FAST RAAT MODE · stale backend invalidation + aggressive recovery probe 시작")\n                    last_tunnel=t\n                    request_recovery(4.0)\n                send_probe()\n            except Exception as e:base.log("R8 RAAT probe 실패: "+repr(e))\n        else:\n            if last_tunnel is not None:\n                invalidate_all("R8 tunnel lost")\n                last_tunnel=None\n        interval=RECOVERY_PROBE_INTERVAL if recovery_active() else PROBE_INTERVAL\n        probe_now.wait(interval);probe_now.clear()\n\n\ndef main():'''
s,n=pat.subn(block,s,count=1)
if n!=1: raise SystemExit('probe loop target not found')

s=s.replace('print("ON RoonLink NetShare PC Relay v2.4 FINAL - STABLE RAAT PROXY")',
            'print("ON RoonLink NetShare PC Relay v2.5 FINAL - FAST RAAT RECOVERY")')
s=s.replace('print("Architecture: native RAAT discovery + fixed PC proxy port + atomic backend target rotation.")',
            'print("Architecture: fixed PC proxy + stale backend invalidation + aggressive fresh-target recovery.")')
s=s.replace('print("If HiBy changes tcp_port, Roon keeps the same proxy; stale backend OPEN_ERR triggers immediate re-probe/retry.")',
            'print("OPEN_ERR quarantines the dead HiBy port; it is never retried until a fresh target is validated.")')

p.write_text(s,encoding='utf-8')
print('PC Relay v2.5 fast backend recovery patch applied')
